];

const CHART_W = 3000;
const CHART_H = 560;

function buildPath(points: number[][], progress: number): string {
  if (points.length === 0) return "";
  // filter points by progress along x axis
  const visible = points.filter((p) => p[0] <= progress);
  if (visible.length === 0) return "";

  // add interpolated endpoint at exact progress position
  const allPoints = [...visible];
  if (progress < 1) {
    const last = points[visible.length - 1];
    const next = points[visible.length] ?? last;
    if (next && last) {
      const segProgress =
        (progress - last[0]) / ((next[0] - last[0]) || 0.001);
      const interpX = last[0] + (next[0] - last[0]) * segProgress;
      const interpY = last[1] + (next[1] - last[1]) * segProgress;
      allPoints.push([interpX, interpY]);
    }
  }

  return allPoints
    .map((p, i) => {
      const x = p[0] * CHART_W;
      const y = p[1] * CHART_H;
      return i === 0 ? `M${x},${y}` : `L${x},${y}`;
    })
    .join(" ");
}

